// Ensure helper exists at request scope
pm.testUtils = pm.testUtils || {};
if (!pm.testUtils.getByPath) {
  pm.testUtils.getByPath = function (obj, path) {
    return String(path || '').split('.').reduce(function (acc, key) {
      return acc == null ? undefined : acc[key];
    }, obj);
  };
}
if (!pm.testUtils.assertMetaProfilesPresent) {
  pm.testUtils.assertMetaProfilesPresent = function (resource, opts) {
    var version = pm.environment.get('VERSION');
    var expected = opts[version] || [];
    var profiles = pm.testUtils.getByPath(resource, opts.path) || [];
    pm.test(opts.label || 'Expected meta.profile values are present', function () {
      pm.expect(profiles, 'meta.profile should be an array at path: ' + opts.path).to.be.an('array');
      expected.forEach(function (profile) {
        pm.expect(profiles).to.include(profile);
      });
    });
  };
}
// Parse a response body without throwing. Returns {} for empty/non-JSON bodies so that
// "server returned nothing useful" surfaces as a failed assertion, not a script TypeError.
if (!pm.testUtils.safeJson) {
  pm.testUtils.safeJson = function (response) {
    try {
      var text = response && response.text ? response.text() : '';
      if (!text) { return {}; }
      return JSON.parse(text);
    } catch (e) {
      return {};
    }
  };
}
if (!pm.testUtils.findValueSetPin) {
// Find the version a manifest (CRMIManifestLibrary / quality-program-cqfm Library) binds for a
// value set canonical. Two mechanisms are supported, because manifests in the wild use either:
//
//   1. relatedArtifact.depends-on with a versioned canonical ("<url>|<version>").
//      This is the shape VSAC's ecqm-update-* manifests use (711 such entries in
//      ecqm-update-2022-05-05, and no contained Parameters at all). CRMI describes resolution
//      for exactly this shape under "Canonical Resolution With a Manifest".
//   2. A manifest-parameters entry in a contained Parameters resource: default-valueset-version
//      (CRMI 2.0.0) or canonicalVersion (the CRMI STU1 spelling, which is what our own
//      Quality Program 6.1 request sends).
//
// Precedence follows CRMI: force- beats an explicit reference version, which beats default-.
// Returns { version, source, candidates } - version is null when the manifest pins nothing.
pm.testUtils.findValueSetPin = function (manifest, vsCanonical) {
  var candidates = [];
  var base = function (canonical) { return String(canonical || '').split('|')[0]; };
  var ver = function (canonical) {
    var parts = String(canonical || '').split('|');
    return parts.length > 1 ? parts.slice(1).join('|') : null;
  };

  var related = (manifest && manifest.relatedArtifact) || [];
  if (Array.isArray(related)) {
    related.forEach(function (ra) {
      if (!ra || !ra.resource) { return; }
      if (base(ra.resource) !== vsCanonical) { return; }
      var v = ver(ra.resource);
      if (v) { candidates.push({ version: v, source: 'relatedArtifact:' + (ra.type || 'unknown') }); }
    });
  }

  var PARAM_NAMES = {
    'force-valueset-version': 3,
    'forceCanonicalVersion': 3,
    'force-canonical-version': 3,
    'default-valueset-version': 1,
    'canonicalVersion': 1,
    'default-canonical-version': 1
  };
  var contained = (manifest && manifest.contained) || [];
  if (Array.isArray(contained)) {
    contained.forEach(function (res) {
      if (!res || res.resourceType !== 'Parameters') { return; }
      (res.parameter || []).forEach(function (p) {
        if (!p || !(p.name in PARAM_NAMES)) { return; }
        var value = p.valueCanonical || p.valueUri || p.valueString || '';
        if (base(value) !== vsCanonical) { return; }
        var v = ver(value);
        if (v) { candidates.push({ version: v, source: 'manifest parameter:' + p.name }); }
      });
    });
  }

  var rank = function (c) {
    if (c.source.indexOf('force') !== -1) { return 3; }
    if (c.source.indexOf('relatedArtifact') === 0) { return 2; }
    return 1;
  };
  candidates.sort(function (a, b) { return rank(b) - rank(a); });
  var winner = candidates.length ? candidates[0] : { version: null, source: null };
  return { version: winner.version, source: winner.source, candidates: candidates };
};
